<?php if(!defined('ABSPATH'))exit;$org=stageart_theme_org('name',get_bloginfo('name'));?></div><footer class="stageart-site-footer"><div class="stageart-container stageart-footer-inner"><div><div class="stageart-footer-name"><?php echo esc_html($org);?></div><small>&copy; <?php echo esc_html((string)wp_date('Y'));?></small></div><?php $social=['x'=>['label'=>'X','icon'=>'x','alt'=>'X'],'instagram'=>['label'=>'Instagram','icon'=>'instagram','alt'=>'Instagram'],'youtube'=>['label'=>'YouTube','icon'=>'youtube','alt'=>'YouTube'],'facebook'=>['label'=>'Facebook','icon'=>'facebook','alt'=>'Facebook']];$links=[];foreach($social as $k=>$info){$url=stageart_theme_org($k);if($url){$icon='https://cdn.simpleicons.org/'.$info['icon'];$links[]='<li><a href="'.esc_url($url).'" target="_blank" rel="noopener noreferrer" aria-label="'.esc_attr($info['label']).'"><img src="'.esc_url($icon).'" alt="'.esc_attr($info['alt']).'" loading="lazy"></a></li>';}}if($links)echo'<ul class="stageart-footer-social">'.implode('',$links).'</ul>';?></div></footer><?php wp_footer();?></body></html>
